https://github.com/typeorm/typeorm/releases/tag/0.3.0

entities and migrations in the datasource options will be the only way to configure

entity example:
```ts
import {
  Entity,
  Column,
  PrimaryGeneratedColumn,
  BeforeInsert,
  BeforeUpdate,
} from 'typeorm/browser';

export interface IProfile {
  id: number;
  name: string;
  data: string;
  createdAt: number;
  updatedAt: number;
}

@Entity({ name: 'profiles' })
export class Profile {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ name: 'name', type: 'varchar', nullable: false })
  name: string;

  @Column({ name: 'data', type: 'text', nullable: false })
  data: string;

  @Column({ name: 'created_at', type: 'datetime' })
  createdAt: number;

  @Column({ name: 'updated_at', type: 'datetime' })
  updatedAt: number;

  @BeforeInsert()
  createDate(): void {
    this.createdAt = Date.now();
    this.updatedAt = Date.now();
  }

  @BeforeUpdate()
  updateDate(): void {
    this.updatedAt = Date.now();
  }
}
```

